/**
 * Printable Maya glyph worksheets (#6921). The data is generated by
 * scripts/learn/maya-worksheets/build.mjs from `maya_signs` and `maya_glyph_blocks`;
 * edit the picks there and rebuild, never this JSON by hand.
 */
import data from './sheets.json';

export interface Img { src: string; w: number; h: number }
export interface Sign extends Img { value: string; missing?: boolean }
export interface Block extends Img {
  id: string; monument: string; coord: string; page: number;
  transliteration: string; transcription: string; translation: string; number?: number;
}

export type Sheet = {
  slug: string; number: number; title: string; level: string; intro: string; credits: CreditKey[];
} & (
  | { layout: 'chart'; chart: { consonant: string; cells: Sign[] }[] }
  | { layout: 'write' | 'trace'; items: (Sign & { answer: string })[] }
  | { layout: 'circle'; items: { prompt: string; options: Sign[]; answer: string }[] }
  | { layout: 'spell-read'; bank: string[]; items: { signs: Sign[]; answer: string }[] }
  | { layout: 'spell-write'; items: { word: string; gloss: string; parts: string[]; answerSigns: Sign[] }[] }
  | { layout: 'pairs'; items: { signs: Sign[]; answer: string }[] }
  | { layout: 'match'; bank: string[]; items: (Sign & { meaning: string; answer: string })[] }
  | { layout: 'numerals'; read: number[]; draw: number[] }
  | { layout: 'blocks-number'; items: Block[] }
  | { layout: 'blocks-word'; helper: Sign[]; items: Block[] }
);

export type CreditKey = 'stuart' | 'twkm' | 'morley' | 'palenque';

export const CREDITS = data.credits as Record<CreditKey, string>;
export const SHEETS = data.sheets as Sheet[];
export const LEVELS = ['Reference', 'Level 1', 'Level 2', 'Level 3', 'Level 4'];

export function getSheet(slug: string): Sheet | undefined {
  return SHEETS.find((s) => s.slug === slug);
}
